dir:



















































































































	select data as id into #id from dbo.ISWIFTFunction$Split(@so_ct, ',')
	select @@fields into #t from v12 a @@join
	  where a.id in (select id from #id)
	  order by a.ngay_ct, a.so_ct

	select * from #t order by line


	select a.ma_noi_di,a.ma_noi_den,a.ma_kh,a.ngay_hl,a.ngay_hld,a.t_tong_trong,a.t_tong_khoi,a.ma_nt,a.cvc_yn, a.xk_yn, a.nk_yn, a.pp_yn,
	b.ten_noi_di,c.ten_noi_den,d.ten_kh, id id_yc, so_ct so_yc from s12 a 
	  left join vdmcangdi b on a.ma_noi_di =b.ma_noi_di 
	  left join vdmcangden c on a.ma_noi_den =c.ma_noi_den 
	  left join dmkh d on a.ma_kh =d.ma_kh
	where a.id in (select top 1 id from #id order by id desc) 









  &DefaultButton;




function filter$s42YG2Select(p){
  this.constructor(p);
}
filter$s42YG2Select.prototype = new DirEvent();
filter$s42YG2Select.prototype.beforeInit = function(){
  var p = this._dir;

}


filter$s42YG2Select.prototype.afterInit = function(){
  var p = this._dir;
  p.valForm(['ngay_ct1','ngay_ct2','id', 'ma_noi_di', 'ten_noi_di', 'ma_noi_den', 'ten_noi_den', 'ma_nt', 'unit_id'], [p.options._ngay_ct1,p.options._ngay_ct2,p.options._so_ct,p.options._ma_noi_di, p.options._ten_noi_di,p.options._ma_noi_den, p.options._ten_noi_den,  p.options._ma_nt, p.options._unit_id]);
	dir$s42YG2SetMaster(p);

}

function dir$s42YG2SetMaster(p) {
  p.request('ma_kh_request', '', ['id']);
}

filter$s42YG2Select.prototype.beforeAcceptFilter = function (m2, opt, sub) {
  var p = this._dir, pa = p.options.parent, g = p.grid(0), dt = g.data, master = g.ds.get(1), rErr = '';

 var fun = function(){
	 // p.valForm(['ngay_ct1','ngay_ct2','id', 'ma_noi_di', 'ten_noi_di', 'ma_noi_den', 'ten_noi_den', 'ma_nt', 'unit_id'], [p.options._ngay_ct1,p.options._ngay_ct2,p.options._so_ct,p.options._ma_noi_di, p.options._ten_noi_di,p.options._ma_noi_den, p.options._ten_noi_den,  p.options._ma_nt, p.options._unit_id]);
    //dt.removeRow('[so_luong0] == 0');
    //pa.appendGrid(0, dt, p.valForm('xprocess') == "2", 'so_luong', 'so_luong0');
   // pa.calcExpressionAll(0, 'so_luong');
    pa.appendForm(master, 0);
    p._close();
	//pa.valForm([ma_noi_den],['ADDD']);
	// p._close();
  }

  if (rErr.length) {
    $.question('$VoucherRetrieveLimit', null, p, function(q, v){
      q._close();
      if (v) fun();
    });
  } else fun();


  //p._close();

  return false;
}









				SELECT distinct ma_cong into #tt FROM v12 a where a.id = @id

				  select top 1 a.ma_kh as [!ma_kh],a.ma_so_thue as [!ma_so_thue], a.ten_kh as [!ten_kh], a.ma_noi_di as [!ma_noi_di], a.ma_noi_den as [!ma_noi_den],
				  a.so_ct as [!so_ct],a.t_tong_trong as [!t_tong_trong],a.t_tong_khoi as [!t_tong_khoi],
					b.ten_noi_di as [!ten_noi_di],c.ten_noi_den as [!ten_noi_den]
				  from s12 a left join vdmcangdi b on a.ma_noi_di =b.ma_noi_di left join vdmcangden c on a.ma_noi_den =c.ma_noi_den
				  where a.id = @id
